import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
import { AdminActivityTables } from "@/components/admin/AdminActivityTables";
import { requireRole } from "@/lib/auth";
import {
  listRecentSessions,
  listRecentPayments,
  listAllPayouts,
} from "@/lib/db/queries";
import { shortDate } from "@/lib/time";
import { t } from "@/lib/i18n";

export const metadata = {
  title: `${t("admin.activityTitle")} · ${t("app.name")}`,
};

export default async function AdminActivityPage() {
  await requireRole("admin");
  const [sessions, payments, payouts] = await Promise.all([
    listRecentSessions(25),
    listRecentPayments(25),
    listAllPayouts(25),
  ]);

  return (
    <div className="flex flex-col gap-8">
      <DashboardHeader
        title={t("admin.activityTitle")}
        description={t("admin.activitySubtitle")}
      />
      <AdminActivityTables
        sessions={sessions.map((s) => ({
          id: s.id,
          dateLabel: shortDate(s.ended_at ?? s.created_at),
          dateMs: new Date(s.ended_at ?? s.created_at).getTime(),
          durationLabel: `${Math.floor(s.elapsed_seconds / 60)}:${String(
            s.elapsed_seconds % 60,
          ).padStart(2, "0")}`,
          totalCents: s.total_price_cents,
          commissionCents: s.commission_cents,
          earningsCents: s.provider_earnings_cents,
          status: s.status,
        }))}
        payments={payments.map((p) => ({
          id: p.id,
          dateLabel: shortDate(p.created_at),
          dateMs: new Date(p.created_at).getTime(),
          amountCents: p.amount_cents,
          status: p.status,
        }))}
        payouts={payouts.map((p) => ({
